INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('terms-of-service','{"en":"Terms of Service"}','{"en":"By using Apex SMM World, you agree to our terms and conditions. Please ensure that all order details are correct before placing an order. Delivery times are estimates and may vary depending on the service. Users must comply with applicable laws and social media platform policies. We reserve the right to update our services and terms when necessary. For assistance, please contact our support team."}',true,true,true,'2026-10-14T13:29:03.627+00:00','2026-10-14T13:31:30.855+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('terms','{"ar":"شروط الخدمة","bn":"ব্যবহারের শর্তাবলি","en":"Terms of Service","fa":"شرایط خدمات","hi":"सेवा की शर्तें","id":"Ketentuan Layanan","tr":"Hizmet Şartları","pt-BR":"Termos de Serviço"}','{"ar":"باستخدامك هذا المتجر، فإنك توافق على تقديم روابط عامة صالحة. نحن غير مسؤولين عن النقص الناتج عن تحديثات المنصات أو الحسابات الخاصة.","bn":"এই স্টোর ব্যবহার করে আপনি বৈধ পাবলিক লিংক দিতে সম্মত হচ্ছেন। প্ল্যাটফর্মের আপডেট বা প্রাইভেট অ্যাকাউন্টের কারণে সংখ্যা কমে গেলে আমরা দায়ী নই।","en":"By using this store you agree to provide valid public links. We are not responsible for drops caused by platform updates or private accounts.","fa":"با استفاده از این فروشگاه، موافقت می‌کنید لینک‌های عمومی معتبر ارائه دهید. ما مسئول ریزش ناشی از به‌روزرسانی‌های پلتفرم یا خصوصی بودن حساب‌ها نیستیم.","hi":"इस स्टोर का उपयोग करके आप मान्य सार्वजनिक लिंक देने के लिए सहमत होते हैं। प्लेटफ़ॉर्म अपडेट या निजी खातों के कारण होने वाली गिरावट के लिए हम ज़िम्मेदार नहीं हैं।","id":"Dengan menggunakan toko ini, Anda setuju untuk memberikan tautan publik yang valid. Kami tidak bertanggung jawab atas penurunan yang disebabkan oleh pembaruan platform atau akun privat.","tr":"Bu mağazayı kullanarak geçerli, herkese açık bağlantılar sağlamayı kabul edersiniz. Platform güncellemeleri veya gizli hesaplar nedeniyle oluşan düşüşlerden sorumlu değiliz.","pt-BR":"Ao usar esta loja, você concorda em fornecer links públicos válidos. Não nos responsabilizamos por quedas causadas por atualizações das plataformas ou contas privadas."}',false,false,true,'2026-11-14T07:56:51.152175+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('policy','{"ar":"السياسة","bn":"নীতিমালা","en":"Policy","fa":"سیاست","hi":"नीति","id":"Kebijakan","tr":"Politika","pt-BR":"Política"}','{"ar":"باستخدامك هذا المتجر، فإنك توافق على تقديم روابط عامة صالحة. نحن غير مسؤولين عن النقص الناتج عن تحديثات المنصات أو الحسابات الخاصة.","bn":"এই স্টোর ব্যবহার করে আপনি বৈধ পাবলিক লিংক দিতে সম্মত হচ্ছেন। প্ল্যাটফর্মের আপডেট বা প্রাইভেট অ্যাকাউন্টের কারণে সংখ্যা কমে গেলে আমরা দায়ী নই।","en":"By using this store you agree to provide valid public links. We are not responsible for drops caused by platform updates or private accounts.","fa":"با استفاده از این فروشگاه، موافقت می‌کنید لینک‌های عمومی معتبر ارائه دهید. ما مسئول ریزش ناشی از به‌روزرسانی‌های پلتفرم یا خصوصی بودن حساب‌ها نیستیم.","hi":"इस स्टोर का उपयोग करके आप मान्य सार्वजनिक लिंक देने के लिए सहमत होते हैं। प्लेटफ़ॉर्म अपडेट या निजी खातों के कारण होने वाली गिरावट के लिए हम ज़िम्मेदार नहीं हैं।","id":"Dengan menggunakan toko ini, Anda setuju untuk memberikan tautan publik yang valid. Kami tidak bertanggung jawab atas penurunan yang disebabkan oleh pembaruan platform atau akun privat.","tr":"Bu mağazayı kullanarak geçerli, herkese açık bağlantılar sağlamayı kabul edersiniz. Platform güncellemeleri veya gizli hesaplar nedeniyle oluşan düşüşlerden sorumlu değiliz.","pt-BR":"Ao usar esta loja, você concorda em fornecer links públicos válidos. Não nos responsabilizamos por quedas causadas por atualizações das plataformas ou contas privadas."}',false,false,true,'2026-11-14T07:56:51.152175+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('privacy','{"ar":"سياسة الخصوصية","bn":"গোপনীয়তা নীতিমালা","en":"Privacy Policy","fa":"سیاست حریم خصوصی","hi":"गोपनीयता नीति","id":"Kebijakan Privasi","tr":"Gizlilik Politikası","pt-BR":"Política de Privacidade"}','{"ar":"نخزّن فقط البيانات اللازمة لتشغيل حسابك: الاسم والبريد الإلكتروني والهاتف والطلبات والمدفوعات. لا نبيع بياناتك أبدًا.","bn":"আপনার অ্যাকাউন্ট চালাতে যতটুকু তথ্য প্রয়োজন, আমরা কেবল ততটুকুই সংরক্ষণ করি: নাম, ইমেইল, ফোন, অর্ডার ও পেমেন্ট। আমরা কখনো আপনার তথ্য বিক্রি করি না।","en":"We store only the data needed to run your account: name, email, phone, orders and payments. We never sell your data.","fa":"ما فقط اطلاعات لازم برای اداره حساب شما را ذخیره می‌کنیم: نام، ایمیل، تلفن، سفارش‌ها و پرداخت‌ها. اطلاعات شما را هرگز نمی‌فروشیم.","hi":"हम केवल आपके खाते को चलाने के लिए आवश्यक डेटा रखते हैं: नाम, ईमेल, फ़ोन, ऑर्डर और भुगतान। हम आपका डेटा कभी नहीं बेचते।","id":"Kami hanya menyimpan data yang diperlukan untuk menjalankan akun Anda: nama, email, telepon, pesanan, dan pembayaran. Kami tidak pernah menjual data Anda.","tr":"Yalnızca hesabınızı işletmek için gereken verileri saklarız: ad, e-posta, telefon, siparişler ve ödemeler. Verilerinizi asla satmayız.","pt-BR":"Armazenamos apenas os dados necessários para operar sua conta: nome, e-mail, telefone, pedidos e pagamentos. Nunca vendemos seus dados."}',false,false,true,'2026-11-14T07:56:51.152175+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('api-policy','{"ar":"سياسة API","bn":"এপিআই নীতিমালা","en":"API Policy","fa":"سیاست API","hi":"API नीति","id":"Kebijakan API","tr":"API Politikası","pt-BR":"Política da API"}','{"ar":"تُخصم تكلفة الطلبات المقدّمة عبر API من رصيدك. لا تشارك مفتاح API الخاص بك.","bn":"এপিআইয়ের মাধ্যমে দেওয়া অর্ডারের মূল্য আপনার ব্যালেন্স থেকে কাটা হয়। আপনার এপিআই চাবি কাউকে দেবেন না।","en":"Orders placed through the API are charged from your balance. Do not share your API key.","fa":"هزینه سفارش‌های ثبت‌شده از طریق API از موجودی شما کسر می‌شود. کلید API خود را به اشتراک نگذارید.","hi":"API से दिए गए ऑर्डर का शुल्क आपके बैलेंस से काटा जाता है। अपनी API कुंजी साझा न करें।","id":"Pesanan melalui API dibebankan dari saldo Anda. Jangan bagikan kunci API Anda.","tr":"API üzerinden verilen siparişlerin ücreti bakiyenizden düşülür. API anahtarınızı paylaşmayın.","pt-BR":"Pedidos feitos pela API são cobrados do seu saldo. Não compartilhe sua chave de API."}',false,false,true,'2026-11-14T07:56:51.152175+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('about','{"ar":"نبذة عنا","bn":"আমাদের সম্পর্কে","en":"About Us","fa":"درباره ما","hi":"हमारे बारे में","id":"Tentang Kami","tr":"Hakkımızda","pt-BR":"Sobre Nós"}','{"ar":"صُمّمت خدماتنا لمساعدتك على تنمية حساباتك على وسائل التواصل الاجتماعي بأمان. بخبرة تتجاوز سنتين، يمكنك الوثوق بنا للحصول على خدمة موثوقة. استخدم خدماتنا بثقة. إذا احتجت إلى مساعدة عاجلة، تواصل مع فريق الدعم عبر لوحة الدعم.","bn":"আমাদের সার্ভিসগুলো আপনার সামাজিক যোগাযোগমাধ্যমের অ্যাকাউন্ট নিরাপদে বাড়াতে সাহায্য করার জন্য তৈরি। দুই বছরেরও বেশি অভিজ্ঞতার কারণে নির্ভরযোগ্য সার্ভিসের জন্য আমাদের ওপর আস্থা রাখতে পারেন। নিশ্চিন্তে আমাদের সার্ভিস ব্যবহার করুন। জরুরি সহায়তা প্রয়োজন হলে সহায়তা প্যানেলের মাধ্যমে আমাদের দলের সঙ্গে যোগাযোগ করুন।","en":"Our services are designed to help you grow your social media accounts safely. With over 2 years of experience, you can trust us for reliable service. Feel free to use our services with confidence. If you need any urgent assistance, please contact our support team through the support panel.","fa":"خدمات ما برای کمک به رشد ایمن حساب‌های شبکه اجتماعی شما طراحی شده‌اند. با بیش از ۲ سال تجربه، می‌توانید برای خدمات قابل اعتماد به ما اطمینان کنید. با خیال راحت از خدمات ما استفاده کنید. برای کمک فوری، از طریق پنل پشتیبانی با تیم ما تماس بگیرید.","hi":"हमारी सेवाएँ आपके सोशल मीडिया खातों को सुरक्षित रूप से बढ़ाने में मदद के लिए बनाई गई हैं। दो वर्षों से अधिक अनुभव के साथ आप विश्वसनीय सेवा के लिए हम पर भरोसा कर सकते हैं। हमारी सेवाओं का विश्वास के साथ उपयोग करें। तत्काल सहायता के लिए सहायता पैनल से हमारी टीम से संपर्क करें।","id":"Layanan kami dirancang untuk membantu Anda mengembangkan akun media sosial dengan aman. Dengan pengalaman lebih dari 2 tahun, Anda dapat mengandalkan layanan kami. Gunakan layanan kami dengan percaya diri. Jika memerlukan bantuan mendesak, hubungi tim kami melalui panel dukungan.","tr":"Hizmetlerimiz sosyal medya hesaplarınızı güvenle büyütmenize yardımcı olmak için tasarlanmıştır. 2 yılı aşkın deneyimimizle güvenilir hizmet için bize güvenebilirsiniz. Hizmetlerimizi güvenle kullanın. Acil yardım gerekiyorsa destek panelinden ekibimizle iletişime geçin.","pt-BR":"Nossos serviços foram criados para ajudar você a desenvolver suas contas de redes sociais com segurança. Com mais de 2 anos de experiência, você pode confiar em nós para um serviço confiável. Use nossos serviços com confiança. Se precisar de assistência urgente, entre em contato com nossa equipe pelo painel de suporte."}',false,false,true,'2026-11-14T07:57:09.515046+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.pages ("slug","title","content","is_custom","show_in_footer","active","updated_at","deleted_at") VALUES ('refund','{"ar":"سياسة الاسترداد والتسليم","bn":"অর্থ ফেরত ও ডেলিভারি নীতিমালা","en":"Refund & Delivery Policy","fa":"سیاست بازپرداخت و تحویل","hi":"धनवापसी और डिलीवरी नीति","id":"Kebijakan Pengembalian Dana dan Pengiriman","tr":"İade ve Teslimat Politikası","pt-BR":"Política de Reembolso e Entrega"}','{"ar":"إذا ألغيت طلبًا لأي سبب، فلن يُردّ مبلغ ذلك الطلب. أما إذا أُلغي الطلب من جانبنا، فسيُعاد المبلغ إلى رصيد حسابك. يرجى ملاحظة أن الأموال المضافة إلى حسابك لا يمكن سحبها.","bn":"আপনি কোনো কারণে অর্ডার বাতিল করলে সেই অর্ডারের টাকা ফেরত দেওয়া হবে না। তবে আমাদের পক্ষ থেকে অর্ডার বাতিল হলে অর্থ আপনার অ্যাকাউন্টের ব্যালেন্সে ফেরত দেওয়া হবে। মনে রাখবেন, অ্যাকাউন্টে যোগ করা টাকা তুলে নেওয়া যায় না।","en":"If you cancel an order for any reason, no refund will be issued for that order. However, if an order is canceled by our , the amount will be refunded to your account balance. Please note that funds added to your account cannot be withdrawn.","fa":"اگر به هر دلیلی سفارش را لغو کنید، مبلغ آن سفارش بازپرداخت نمی‌شود. اما اگر سفارش از طرف ما لغو شود، مبلغ به موجودی حساب شما بازگردانده می‌شود. وجه اضافه‌شده به حساب قابل برداشت نیست.","hi":"यदि आप किसी कारण से ऑर्डर रद्द करते हैं, तो उस ऑर्डर की धनवापसी नहीं होगी। यदि हमारी ओर से ऑर्डर रद्द होता है, तो राशि आपके खाते के बैलेंस में वापस मिलेगी। खाते में जोड़ी गई राशि निकाली नहीं जा सकती।","id":"Jika Anda membatalkan pesanan karena alasan apa pun, tidak ada pengembalian dana untuk pesanan tersebut. Namun, jika pesanan dibatalkan oleh pihak kami, jumlahnya dikembalikan ke saldo akun Anda. Dana yang ditambahkan ke akun tidak dapat ditarik.","tr":"Herhangi bir nedenle siparişi siz iptal ederseniz o sipariş için iade yapılmaz. Ancak sipariş tarafımızdan iptal edilirse tutar hesap bakiyenize iade edilir. Hesabınıza yüklenen para çekilemez.","pt-BR":"Se você cancelar um pedido por qualquer motivo, não haverá reembolso desse pedido. Porém, se o pedido for cancelado por nós, o valor será devolvido ao saldo da sua conta. Os fundos adicionados à conta não podem ser sacados."}',false,false,true,'2026-11-14T07:57:09.515046+00:00',NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('00000000-0000-4000-8000-000000000a03','{"ar":"هل يمكن استخدام هذه الخدمة لتحقيق الدخل؟","bn":"এই সার্ভিস কি আয় করার জন্য ব্যবহার করা যায়?","en":"Can this service be used for monetization?","fa":"آیا این سرویس برای درآمدزایی قابل استفاده است؟","hi":"क्या इस सेवा का उपयोग कमाई के लिए किया जा सकता है?","id":"Apakah layanan ini dapat digunakan untuk monetisasi?","tr":"Bu hizmet para kazanmak için kullanılabilir mi?","pt-BR":"Este serviço pode ser usado para monetização?"}','{"ar":"نعم، يمكن استخدام خدماتنا لتنمية حساباتك بهدف تحقيق الدخل. لكن يجب الالتزام بشروط وسياسات المنصة المعنية للتأهل للموافقة على تحقيق الدخل.","bn":"হ্যাঁ, আয় করার উদ্দেশ্যে আপনার সামাজিক যোগাযোগমাধ্যমের অ্যাকাউন্ট বাড়াতে আমাদের সার্ভিস ব্যবহার করতে পারেন। তবে আয় করার অনুমোদন পেতে সংশ্লিষ্ট প্ল্যাটফর্মের শর্তাবলি ও নীতিমালা অবশ্যই অনুসরণ করুন।","en":"Yes, our services can be used to grow your social media accounts for monetization purposes. However, please ensure that you follow the respective platform’s terms and policies to qualify for monetization approval.","fa":"بله، خدمات ما می‌توانند برای رشد حساب‌های شبکه اجتماعی با هدف درآمدزایی استفاده شوند. برای تأیید درآمدزایی، شرایط و سیاست‌های پلتفرم مربوط را رعایت کنید.","hi":"हाँ, कमाई के उद्देश्य से अपने सोशल मीडिया खाते बढ़ाने के लिए हमारी सेवाएँ उपयोग कर सकते हैं। कमाई की मंज़ूरी के लिए संबंधित प्लेटफ़ॉर्म की शर्तों और नीतियों का पालन करें।","id":"Ya, layanan kami dapat digunakan untuk mengembangkan akun media sosial untuk monetisasi. Namun, patuhi ketentuan dan kebijakan platform terkait agar memenuhi syarat persetujuan monetisasi.","tr":"Evet, hizmetlerimiz sosyal medya hesaplarınızı para kazanma amacıyla büyütmek için kullanılabilir. Ancak onay alabilmek için ilgili platformun şartlarına ve politikalarına uyun.","pt-BR":"Sim, nossos serviços podem ajudar a desenvolver suas contas para monetização. Porém, siga os termos e políticas de cada plataforma para se qualificar para aprovação."}',3,true,'2026-10-04T08:05:42.280162+00:00',NULL,true,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('00000000-0000-4000-8000-000000000a04','{"ar":"حسابي خاص، ماذا أفعل؟","bn":"আমার অ্যাকাউন্ট ব্যক্তিগত, এখন কী করব?","en":"My account is private, what now?","fa":"حسابم خصوصی است، چه کنم؟","hi":"मेरा खाता निजी है, अब क्या करूँ?","id":"Akun saya privat, apa yang harus dilakukan?","tr":"Hesabım gizli, ne yapmalıyım?","pt-BR":"Minha conta é privada, o que faço?"}','{"ar":"اجعل الملف أو المنشور عامًا قبل الطلب، وإلا فقد يفشل التسليم.","bn":"অর্ডার দেওয়ার আগে প্রোফাইল বা পোস্ট সবার জন্য উন্মুক্ত করুন; অন্যথায় ডেলিভারি ব্যর্থ হতে পারে।","en":"Make the profile or post public before ordering, otherwise delivery may fail.","fa":"پیش از سفارش، پروفایل یا پست را عمومی کنید؛ در غیر این صورت تحویل ممکن است ناموفق باشد.","hi":"ऑर्डर से पहले प्रोफ़ाइल या पोस्ट सार्वजनिक करें, अन्यथा डिलीवरी असफल हो सकती है।","id":"Jadikan profil atau postingan publik sebelum memesan, jika tidak pengiriman bisa gagal.","tr":"Sipariş vermeden önce profili veya gönderiyi herkese açık yapın; aksi halde teslimat başarısız olabilir.","pt-BR":"Torne o perfil ou a publicação públicos antes de pedir; caso contrário, a entrega pode falhar."}',4,true,'2026-10-04T08:05:42.280162+00:00',NULL,true,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('0930ee28-93b3-44f9-8dd0-5562a739952d','{"ar":"لماذا إيداعي قيد الانتظار؟","bn":"আমার জমা টাকা অপেক্ষমাণ কেন?","en":"Why is my deposit pending?","fa":"چرا واریزم در انتظار است؟","hi":"मेरी जमा राशि लंबित क्यों है?","id":"Mengapa deposit saya tertunda?","tr":"Yatırdığım para neden beklemede?","pt-BR":"Por que meu depósito está pendente?"}','{"ar":"تُتحقق الإيداعات تلقائيًا؛ تحتاج بعض الطرق إلى دقائق قليلة أو مراجعة يدوية.","bn":"জমা টাকা স্বয়ংক্রিয়ভাবে যাচাই করা হয়; কিছু পদ্ধতিতে কয়েক মিনিট বা হাতে যাচাই করার প্রয়োজন হয়।","en":"Deposits are verified automatically; some methods need a few minutes or a manual check.","fa":"واریزها خودکار بررسی می‌شوند؛ برخی روش‌ها چند دقیقه یا بررسی دستی نیاز دارند.","hi":"जमा राशि अपने आप सत्यापित होती है; कुछ तरीकों में कुछ मिनट या मैन्युअल जाँच लगती है।","id":"Deposit diverifikasi otomatis; beberapa metode memerlukan beberapa menit atau pemeriksaan manual.","tr":"Para yatırma işlemleri otomatik doğrulanır; bazı yöntemler birkaç dakika veya manuel kontrol gerektirir.","pt-BR":"Os depósitos são verificados automaticamente; alguns métodos precisam de alguns minutos ou de uma conferência manual."}',18,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('00000000-0000-4000-8000-000000000a01','{"ar":"كم يستغرق التسليم؟","bn":"ডেলিভারি হতে কত সময় লাগে?","en":"How long does delivery take?","fa":"تحویل چقدر طول می‌کشد؟","hi":"डिलीवरी में कितना समय लगता है?","id":"Berapa lama waktu pengiriman?","tr":"Teslimat ne kadar sürer?","pt-BR":"Quanto tempo leva a entrega?"}','{"ar":"ستُنجز كل خدمة خلال وقت المعالجة التقديري لها. يتعامل فريقنا مع كل طلب بأقصى عناية ويمنحه أعلى أولوية.","bn":"প্রতিটি সার্ভিস তার আনুমানিক প্রক্রিয়াকরণ সময়ের মধ্যে সম্পন্ন হবে। আমাদের দল প্রতিটি অর্ডার অত্যন্ত যত্নের সঙ্গে পরিচালনা করে এবং সর্বোচ্চ অগ্রাধিকার দেয়।","en":"Each service will be completed within its estimated processing time. Our team handles every order with the utmost care and gives it the highest priority.","fa":"هر سرویس در زمان پردازش تخمینی خود تکمیل می‌شود. تیم ما هر سفارش را با نهایت دقت و بالاترین اولویت رسیدگی می‌کند.","hi":"हर सेवा अपने अनुमानित प्रक्रिया समय के भीतर पूरी होगी। हमारी टीम हर ऑर्डर को पूरी सावधानी और सर्वोच्च प्राथमिकता देती है।","id":"Setiap layanan akan selesai dalam perkiraan waktu pemrosesannya. Tim kami menangani setiap pesanan dengan sangat hati-hati dan memberi prioritas tertinggi.","tr":"Her hizmet tahmini işlem süresi içinde tamamlanır. Ekibimiz her siparişi büyük özenle ele alır ve en yüksek önceliği verir.","pt-BR":"Cada serviço será concluído dentro do prazo estimado de processamento. Nossa equipe trata cada pedido com o máximo cuidado e a mais alta prioridade."}',1,true,'2026-10-04T08:05:42.280162+00:00',NULL,true,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('00000000-0000-4000-8000-000000000a02','{"ar":"كيف أضيف رصيدًا؟","bn":"আমি কীভাবে ফান্ড যোগ করব?","en":"How do I add funds?","fa":"چگونه موجودی اضافه کنم؟","hi":"मैं फंड कैसे जोड़ूँ?","id":"Bagaimana cara menambah saldo?","tr":"Nasıl bakiye yüklerim?","pt-BR":"Como adiciono saldo?"}','{"ar":"افتح إضافة الأموال واختر Binance أو USDT أو P2P (bKash، Nagad، Rocket)، وأرسل الدفع ثم قدّم معرّف المعاملة. سيوافق المسؤول قريبًا.","bn":"ফান্ড যোগ করুন খুলে Binance, USDT অথবা P2P (বিকাশ, নগদ, রকেট) নির্বাচন করুন, অর্থ পাঠিয়ে লেনদেনের নম্বর জমা দিন। একজন প্রশাসক অল্প সময়ের মধ্যে অনুমোদন দেবেন।","en":"Open Add Funds, choose Binance, USDT or P2P (bKash, Nagad, Rocket), send the payment and submit the Transaction ID. An admin approves it shortly.","fa":"افزودن موجودی را باز کنید، Binance، USDT یا P2P (bKash، Nagad، Rocket) را انتخاب کنید، پرداخت را ارسال و شناسه تراکنش را ثبت کنید. مدیر به‌زودی تأیید می‌کند.","hi":"फंड जोड़ें खोलें, Binance, USDT या P2P (bKash, Nagad, Rocket) चुनें, भुगतान भेजें और लेनदेन ID जमा करें। व्यवस्थापक जल्द अनुमोदन करेगा।","id":"Buka Tambah Saldo, pilih Binance, USDT atau P2P (bKash, Nagad, Rocket), kirim pembayaran dan masukkan ID transaksi. Admin segera menyetujuinya.","tr":"Bakiye Yükle bölümünü açın, Binance, USDT veya P2P (bKash, Nagad, Rocket) seçin, ödemeyi gönderip işlem kimliğini iletin. Yönetici kısa sürede onaylar.","pt-BR":"Abra Adicionar Saldo, escolha Binance, USDT ou P2P (bKash, Nagad, Rocket), envie o pagamento e informe o ID da transação. Um administrador aprovará em breve."}',2,true,'2026-10-04T08:05:42.280162+00:00',NULL,true,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('7c0c71b9-1d12-436b-9562-7070c946f6bb','{"ar":"كيف أقدّم طلبًا؟","bn":"আমি কীভাবে অর্ডার দেব?","en":"How do I place an order?","fa":"چگونه سفارش ثبت کنم؟","hi":"मैं ऑर्डर कैसे दूँ?","id":"Bagaimana cara membuat pesanan?","tr":"Nasıl sipariş veririm?","pt-BR":"Como faço um pedido?"}','{"ar":"افتح طلبًا جديدًا، واختر المنصة والفئة والخدمة، والصق الرابط وأدخل الكمية ثم اضغط إرسال.","bn":"নতুন অর্ডার খুলুন, প্ল্যাটফর্ম, বিভাগ ও সার্ভিস নির্বাচন করুন, লিংক দিন, পরিমাণ লিখুন এবং জমা দিন বোতামে চাপ দিন।","en":"Open New Order, choose a platform, category and service, paste your link, enter the quantity and press Submit.","fa":"سفارش جدید را باز کنید، پلتفرم، دسته و سرویس را انتخاب کنید، لینک و تعداد را وارد و ارسال را بزنید.","hi":"नया ऑर्डर खोलें, प्लेटफ़ॉर्म, श्रेणी और सेवा चुनें, लिंक चिपकाएँ, मात्रा दर्ज करें और जमा करें दबाएँ।","id":"Buka Pesanan Baru, pilih platform, kategori dan layanan, tempel tautan, masukkan jumlah dan tekan Kirim.","tr":"Yeni Sipariş bölümünde platform, kategori ve hizmet seçin, bağlantıyı yapıştırın, miktarı girip Gönder''e basın.","pt-BR":"Abra Novo Pedido, escolha plataforma, categoria e serviço, cole o link, informe a quantidade e clique em Enviar."}',10,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('b0d1e7c8-21d1-4ada-8893-816652cd9beb','{"ar":"ماذا لو اكتمل طلبي جزئيًا؟","bn":"আমার অর্ডার আংশিক সম্পন্ন হলে কী হবে?","en":"What if my order is partial?","fa":"اگر سفارشم جزئی تکمیل شود چه می‌شود؟","hi":"मेरा ऑर्डर आंशिक हो तो क्या होगा?","id":"Bagaimana jika pesanan saya selesai sebagian?","tr":"Siparişim kısmen tamamlanırsa ne olur?","pt-BR":"E se meu pedido for parcial?"}','{"ar":"يُعاد مبلغ الجزء غير المسلّم إلى رصيدك تلقائيًا.","bn":"যতটুকু ডেলিভারি হয়নি তার টাকা স্বয়ংক্রিয়ভাবে আপনার ব্যালেন্সে ফেরত দেওয়া হয়।","en":"The undelivered part is refunded to your balance automatically.","fa":"مبلغ بخش تحویل‌نشده خودکار به موجودی شما بازگردانده می‌شود.","hi":"जो हिस्सा डिलीवर नहीं हुआ उसकी राशि अपने आप आपके बैलेंस में वापस आती है।","id":"Bagian yang tidak terkirim otomatis dikembalikan ke saldo Anda.","tr":"Teslim edilmeyen kısmın tutarı otomatik olarak bakiyenize iade edilir.","pt-BR":"A parte não entregue é reembolsada automaticamente ao seu saldo."}',13,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('2fbc9d08-3b43-4658-bdd4-326361b45ee3','{"ar":"هل يمكنني إلغاء طلب؟","bn":"আমি কি অর্ডার বাতিল করতে পারি?","en":"Can I cancel an order?","fa":"آیا می‌توانم سفارش را لغو کنم؟","hi":"क्या मैं ऑर्डर रद्द कर सकता हूँ?","id":"Bisakah saya membatalkan pesanan?","tr":"Siparişi iptal edebilir miyim?","pt-BR":"Posso cancelar um pedido?"}','{"ar":"يمكن إلغاء الطلبات المعلّقة التي لم تبدأ من سجل الطلبات واسترداد المبلغ كاملًا.","bn":"শুরু হয়নি এমন অপেক্ষমাণ অর্ডার অর্ডারের ইতিহাস থেকে বাতিল করে পুরো টাকা ফেরত পাওয়া যায়।","en":"Pending orders that have not started can be canceled from Order History for a full refund.","fa":"سفارش‌های در انتظار که شروع نشده‌اند را می‌توان از تاریخچه سفارش لغو و مبلغ کامل را دریافت کرد.","hi":"जो लंबित ऑर्डर शुरू नहीं हुए हैं, उन्हें ऑर्डर इतिहास से रद्द करके पूरा धन वापस पाया जा सकता है।","id":"Pesanan tertunda yang belum dimulai dapat dibatalkan dari Riwayat Pesanan untuk pengembalian dana penuh.","tr":"Henüz başlamamış bekleyen siparişler Sipariş Geçmişi üzerinden tam iade için iptal edilebilir.","pt-BR":"Pedidos pendentes que ainda não começaram podem ser cancelados no Histórico de Pedidos com reembolso total."}',14,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('07f24524-6531-4714-a4b8-b7b0a85afdc7','{"ar":"هل حسابي آمن؟","bn":"আমার অ্যাকাউন্ট কি নিরাপদ?","en":"Is my account safe?","fa":"آیا حسابم امن است؟","hi":"क्या मेरा खाता सुरक्षित है?","id":"Apakah akun saya aman?","tr":"Hesabım güvende mi?","pt-BR":"Minha conta está segura?"}','{"ar":"نعم. لا نطلب كلمات مرور حساباتك الاجتماعية أبدًا؛ نحتاج فقط إلى رابط عام.","bn":"হ্যাঁ। আমরা কখনো আপনার সামাজিক যোগাযোগমাধ্যমের পাসওয়ার্ড চাই না; শুধু সবার জন্য উন্মুক্ত একটি লিংক প্রয়োজন।","en":"Yes. We never ask for your social media passwords; only a public link is needed.","fa":"بله. هرگز رمز عبور شبکه اجتماعی شما را نمی‌خواهیم؛ فقط یک لینک عمومی لازم است.","hi":"हाँ। हम सोशल मीडिया पासवर्ड कभी नहीं माँगते; केवल सार्वजनिक लिंक चाहिए।","id":"Ya. Kami tidak pernah meminta kata sandi media sosial Anda; hanya tautan publik yang diperlukan.","tr":"Evet. Sosyal medya şifrelerinizi asla istemeyiz; yalnızca herkese açık bağlantı gerekir.","pt-BR":"Sim. Nunca pedimos suas senhas de redes sociais; apenas um link público é necessário."}',15,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('1a44a7d0-18b1-425d-987f-22bd1f95675b','{"ar":"ما هو التعويض؟","bn":"রিফিল কী?","en":"What is refill?","fa":"ریفیل چیست؟","hi":"रिफिल क्या है?","id":"Apa itu isi ulang?","tr":"Yenileme nedir?","pt-BR":"O que é reposição?"}','{"ar":"تتضمن بعض الخدمات تعويضًا. إذا انخفضت الأعداد خلال فترة التعويض، افتح تذكرة برقم الطلب.","bn":"কিছু সার্ভিসে রিফিল থাকে। রিফিলের সময়সীমার মধ্যে সংখ্যা কমে গেলে অর্ডার নম্বর দিয়ে একটি সহায়তা টিকিট খুলুন।","en":"Some services include refill. If counts drop within the refill period, open a ticket with your Order ID.","fa":"برخی خدمات شامل ریفیل هستند. اگر در دوره ریفیل تعداد کاهش یافت، با شناسه سفارش تیکت باز کنید.","hi":"कुछ सेवाओं में रिफिल शामिल है। रिफिल अवधि में संख्या कम हो तो ऑर्डर ID के साथ टिकट खोलें।","id":"Beberapa layanan menyertakan isi ulang. Jika jumlah turun selama periode isi ulang, buat tiket dengan ID pesanan.","tr":"Bazı hizmetlerde yenileme vardır. Yenileme süresi içinde sayılar düşerse sipariş kimliğinizle destek talebi açın.","pt-BR":"Alguns serviços incluem reposição. Se as contagens caírem no período de reposição, abra um ticket com o ID do pedido."}',16,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('f3849177-7b20-4383-b101-812e81363a8e','{"ar":"كيف أتواصل مع الدعم؟","bn":"সহায়তা দলের সঙ্গে কীভাবে যোগাযোগ করব?","en":"How do I contact support?","fa":"چگونه با پشتیبانی تماس بگیرم؟","hi":"सहायता से कैसे संपर्क करूँ?","id":"Bagaimana cara menghubungi dukungan?","tr":"Destekle nasıl iletişime geçerim?","pt-BR":"Como entro em contato com o suporte?"}','{"ar":"أنشئ تذكرة من تذاكري أو استخدم زر WhatsApp. نرد على مدار الساعة.","bn":"আমার টিকিট থেকে একটি টিকিট তৈরি করুন অথবা WhatsApp বোতাম ব্যবহার করুন। আমরা দিনরাত উত্তর দিই।","en":"Create a ticket from My Tickets or use the WhatsApp button. We reply 24/7.","fa":"از تیکت‌های من تیکت بسازید یا از دکمه WhatsApp استفاده کنید. شبانه‌روز پاسخ می‌دهیم.","hi":"मेरे टिकट से टिकट बनाएँ या WhatsApp बटन उपयोग करें। हम चौबीसों घंटे जवाब देते हैं।","id":"Buat tiket dari Tiket Saya atau gunakan tombol WhatsApp. Kami membalas 24/7.","tr":"Destek Taleplerim bölümünden talep açın veya WhatsApp düğmesini kullanın. 7/24 yanıt veririz.","pt-BR":"Crie um ticket em Meus Tickets ou use o botão do WhatsApp. Respondemos 24 horas por dia."}',17,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('b98f9e2c-17af-4969-aa6b-3c8524ff5cdb','{"ar":"هل لديكم API؟","bn":"আপনাদের কি এপিআই আছে?","en":"Do you have an API?","fa":"آیا API دارید؟","hi":"क्या आपके पास API है?","id":"Apakah Anda menyediakan API?","tr":"API sunuyor musunuz?","pt-BR":"Vocês têm uma API?"}','{"ar":"نعم. يمكن للموزعين استخدام API الموزعين من القائمة لربط لوحاتهم الخاصة.","bn":"হ্যাঁ। পুনর্বিক্রেতারা মেনুর রিসেলার এপিআই ব্যবহার করে নিজেদের প্যানেল যুক্ত করতে পারেন।","en":"Yes. Resellers can use the Reseller API from the menu to connect their own panel.","fa":"بله. فروشندگان می‌توانند از API فروشندگان در منو برای اتصال پنل خود استفاده کنند.","hi":"हाँ। रीसेलर अपना पैनल जोड़ने के लिए मेनू से रीसेलर API उपयोग कर सकते हैं।","id":"Ya. Reseller dapat menggunakan API Reseller dari menu untuk menghubungkan panel mereka.","tr":"Evet. Bayiler menüdeki Bayi API bölümünü kullanarak kendi panellerini bağlayabilir.","pt-BR":"Sim. Revendedores podem usar a API de Revenda no menu para conectar seu próprio painel."}',19,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('e77a94e0-a642-457e-91a0-162e9e4639b9','{"ar":"هل يمكنني الطلب لأي رابط؟","bn":"যেকোনো লিংকের জন্য কি অর্ডার দিতে পারি?","en":"Can I order for any link?","fa":"آیا برای هر لینکی می‌توانم سفارش دهم؟","hi":"क्या किसी भी लिंक के लिए ऑर्डर दे सकता हूँ?","id":"Bisakah saya memesan untuk tautan apa pun?","tr":"Her bağlantı için sipariş verebilir miyim?","pt-BR":"Posso pedir para qualquer link?"}','{"ar":"يجب أن يكون الرابط عامًا. لا يمكن التسليم للحسابات الخاصة أو المنشورات المحذوفة.","bn":"লিংকটি সবার জন্য উন্মুক্ত হতে হবে। ব্যক্তিগত অ্যাকাউন্ট বা মুছে ফেলা পোস্টে ডেলিভারি সম্ভব নয়।","en":"The link must be public. Private accounts or deleted posts cannot be delivered.","fa":"لینک باید عمومی باشد. تحویل برای حساب خصوصی یا پست حذف‌شده ممکن نیست.","hi":"लिंक सार्वजनिक होना चाहिए। निजी खातों या हटाई गई पोस्ट पर डिलीवरी नहीं हो सकती।","id":"Tautan harus publik. Akun privat atau postingan yang dihapus tidak dapat menerima pengiriman.","tr":"Bağlantı herkese açık olmalıdır. Gizli hesaplara veya silinmiş gönderilere teslimat yapılamaz.","pt-BR":"O link deve ser público. Contas privadas ou publicações excluídas não podem receber a entrega."}',20,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
INSERT INTO public.qna ("id","question","answer","sort","active","created_at","deleted_at","show_on_home","home_sort") VALUES ('b16aafad-a3dd-40c8-9bbf-f7c8f822b2ab','{"ar":"كيف تعمل مستويات الحساب؟","bn":"অ্যাকাউন্টের স্তর কীভাবে কাজ করে?","en":"How do account levels work?","fa":"سطح‌های حساب چگونه کار می‌کنند؟","hi":"खाते के स्तर कैसे काम करते हैं?","id":"Bagaimana cara kerja level akun?","tr":"Hesap seviyeleri nasıl çalışır?","pt-BR":"Como funcionam os níveis da conta?"}','{"ar":"يرتفع مستواك مع إجمالي الإيداعات. اضغط على شارتك لرؤية جميع المستويات.","bn":"মোট জমা টাকার সঙ্গে আপনার স্তর বাড়ে। সব স্তর দেখতে আপনার ব্যাজে চাপ দিন।","en":"Your level grows with total deposits. Tap your badge to see all levels.","fa":"سطح شما با مجموع واریزها افزایش می‌یابد. برای دیدن همه سطح‌ها روی نشان خود بزنید.","hi":"कुल जमा राशि के साथ आपका स्तर बढ़ता है। सभी स्तर देखने के लिए बैज पर टैप करें।","id":"Level Anda meningkat seiring total deposit. Ketuk lencana Anda untuk melihat semua level.","tr":"Toplam yatırdığınız tutarla seviyeniz yükselir. Tüm seviyeleri görmek için rozetinize dokunun.","pt-BR":"Seu nível aumenta com o total de depósitos. Toque no seu selo para ver todos os níveis."}',21,true,'2026-11-12T09:49:37.772259+00:00',NULL,false,0) ON CONFLICT DO NOTHING;
