INSERT INTO public.ui_labels ("key","page_group","default_text","translations","rich","updated_at") VALUES ('home.hero_text','Home','Boost your social media presence with affordable, high-quality services. Get social media followers, likes, views, and more at competitive prices. Enjoy a smooth, user-friendly platform designed for your convenience. Grow your brand, reach a wider audience, and stand out from the competition. Whether you''re a creator, influencer, business owner, or reseller, we''ve got you covered. Experience convenient ordering, fast processing, and dedicated customer support. Make social media growth easier, smarter, and more affordable than ever.','{"en":"Boost your social media presence with affordable, high-quality services. Get social media followers, likes, views, and more at competitive prices. Enjoy a smooth, user-friendly platform designed for your convenience. Grow your brand, reach a wider audience, and stand out from the competition. Whether you''re a creator, influencer, business owner, or reseller, we''ve got you covered. Experience convenient ordering, fast processing, and dedicated customer support. Make social media growth easier, smarter, and more affordable than ever."}',true,'2026-10-09T05:18:09.042+00:00') ON CONFLICT DO NOTHING;
