INSERT INTO public.giveaway_settings ("id","config","updated_at") VALUES (1,'{"rules":"You must be a registered user of Apex SMM World.\nMinimum Activity Requirement: your account must have at least 1 completed paid order to participate.\nSingle Claim: each reward can be claimed only once per user unless clearly stated otherwise.\nOne Account Only: creating multiple accounts is strictly prohibited. Accounts detected through IP/device fingerprinting or fraud signals will be banned and rewards forfeited.\nOriginal & Public Content: submitted work must be original, public and remain visible online for at least 1 year.\nVerification Timeline: verification takes 6–72 hours (manual review may take longer).\nManual Review: balance is added only after verification by our moderation team.\nDisqualification: fake, duplicate, deleted or private posts will be disqualified and rewards cancelled.\nAnti-Botting Notice: botting, view farming or artificial engagement will result in a permanent ban from the campaign.","steps":["Complete the Task","Submit Your Proof","Receive Your Rewards"],"tasks":[{"id":"youtube-review","how":"Create an original video about your experience with Apex SMM World.\nInclude https://apexsmmworld.com in the video description.\nSubmit the public video link for review.","title":"YouTube Review Giveaway","active":true,"reward":2,"summary":"Share your honest experience in a YouTube video.","currency":"USD","platform":"youtube","conditions":"Use your own content.\nThe video must be publicly accessible.\nRewards require manual approval; submitting proof does not guarantee a reward."},{"id":"facebook-post","how":"Write an original post about your experience.\nInclude https://apexsmmworld.com and submit the public post link.","title":"Facebook Giveaway","active":true,"reward":1,"summary":"Share your experience in an original Facebook post.","currency":"USD","platform":"facebook","conditions":"The post must be original and public.\nOne submission per account.\nRewards require manual approval."},{"id":"tiktok-video","how":"Create an original TikTok video about your experience.\nMention Apex SMM World and submit the public video link.","title":"TikTok Giveaway","active":true,"reward":1,"summary":"Create an original TikTok about Apex SMM World.","currency":"USD","platform":"tiktok","conditions":"The video must be original and public.\nOne submission per account.\nRewards require manual approval."},{"id":"linkedin-post","how":"Write an original LinkedIn post about your experience.\nInclude https://apexsmmworld.com and submit the public post link.","title":"LinkedIn Giveaway","active":true,"reward":1,"summary":"Share your honest experience with your network.","currency":"USD","platform":"linkedin","conditions":"The post must be original and public.\nOne submission per account.\nRewards require manual approval."}],"title":"Giveaway","description":"Complete simple social tasks and submit your original work for a balance reward."}','2026-11-12T07:06:50.362341+00:00') ON CONFLICT DO NOTHING;
